int[] power = {40, 85, 30, 95, 60};
int sum = 0;
int max = power[0];
for (int p : power) {
    sum += p;
    if (p > max) max = p;
}
System.out.println("Total: " + sum); // 310
System.out.println("Max: " + max);   // 95

